    function getVal(key, def) {
        try {
            const v = localStorage.getItem('guoba_' + key);
            return v !== null ? JSON.parse(v) : def;
        } catch { return def; }
    }
    function setVal(key, val) {
        localStorage.setItem('guoba_' + key, JSON.stringify(val));
    }
